use crate::inflection::ascii;

pub fn camelize(bytes: &[u8]) -> Vec<u8> {
    let mut result = Vec::with_capacity(bytes.len());
    let mut uppercase_next = false;

    for byte in bytes {
        if *byte == b'_' {
            uppercase_next = true;
            continue;
        }

        if uppercase_next {
            result.push(ascii::to_ascii_upper(*byte));
            uppercase_next = false;
        } else {
            result.push(*byte);
        }
    }

    result
}

pub fn camelize_with_lower_first(bytes: &[u8], lower_first: bool) -> Vec<u8> {
    let camelized = camelize(bytes);
    if lower_first {
        camelized
    } else {
        ascii::uppercase_first(&camelized)
    }
}

pub fn underscore(bytes: &[u8]) -> Vec<u8> {
    let mut result = Vec::with_capacity(bytes.len() * 2);

    for (index, byte) in bytes.iter().enumerate() {
        if ascii::is_ascii_upper(*byte) {
            if index != 0 {
                result.push(b'_');
            }
            result.push(ascii::to_ascii_lower(*byte));
        } else {
            result.push(*byte);
        }
    }

    result
}

pub fn humanize(bytes: &[u8]) -> Vec<u8> {
    let mut result = bytes
        .iter()
        .map(|byte| if *byte == b'_' { b' ' } else { *byte })
        .collect::<Vec<u8>>();

    if let Some(first) = result.first_mut() {
        *first = ascii::to_ascii_upper(*first);
    }

    result
}

pub fn titleize(bytes: &[u8]) -> Vec<u8> {
    let lower = ascii::lowercase_all(bytes);
    let mut result = Vec::with_capacity(lower.len());
    let mut uppercase_next = true;

    for byte in lower {
        if uppercase_next {
            result.push(ascii::to_ascii_upper(byte));
        } else {
            result.push(byte);
        }
        uppercase_next = byte == b' ';
    }

    result
}

pub fn dasherize(bytes: &[u8]) -> Vec<u8> {
    bytes.iter()
        .map(|byte| if *byte == b'_' { b'-' } else { *byte })
        .collect()
}

pub fn parameterize(bytes: &[u8]) -> Vec<u8> {
    let mut result = Vec::with_capacity(bytes.len());

    for byte in bytes {
        let lower = ascii::to_ascii_lower(*byte);
        if ascii::is_ascii_alnum(lower) {
            result.push(lower);
        } else if lower == b' ' {
            result.push(b'-');
        }
    }

    trim_dashes(result)
}

pub fn upcase(bytes: &[u8]) -> Vec<u8> {
    ascii::uppercase_all(bytes)
}

pub fn downcase(bytes: &[u8]) -> Vec<u8> {
    ascii::lowercase_all(bytes)
}

pub fn capitalize(bytes: &[u8]) -> Vec<u8> {
    ascii::capitalize(bytes)
}

pub fn decapitalize(bytes: &[u8]) -> Vec<u8> {
    ascii::lowercase_first(bytes)
}

pub fn truncate(bytes: &[u8], length: usize) -> Vec<u8> {
    if bytes.len() <= length {
        return bytes.to_vec();
    }

    let prefix_length = length.saturating_sub(3);
    let mut result = bytes[..prefix_length].to_vec();
    result.extend_from_slice(b"...");
    result
}

pub fn demodulize(bytes: &[u8]) -> Vec<u8> {
    let last_colon = bytes
        .iter()
        .rposition(|byte| *byte == b':')
        .expect("demodulize expects at least one colon");
    let start = last_colon + 2;
    bytes[start..].to_vec()
}

fn trim_dashes(bytes: Vec<u8>) -> Vec<u8> {
    let mut start = 0;
    let mut end = bytes.len();

    while start < end && bytes[start] == b'-' {
        start += 1;
    }

    while end > start && bytes[end - 1] == b'-' {
        end -= 1;
    }

    bytes[start..end].to_vec()
}

